  // ── Screen: atlas ──────────────────────────────────────────────────────────
  'help.ctx.atlas.title': 'Atlas',
  'help.ctx.atlas.summary':
    'Atlas dünya xəritəsində səyahət izinizdir: səyahətlərinizin sizi apardığı hər ölkə rənglənir, TREK-dən əvvəl ziyarət etdiyiniz ölkələri isə əl ilə əlavə edə bilərsiniz. Regionları görmək üçün xəritəni yaxınlaşdırın, hələ görmək istədiyiniz yerlərin arzular siyahısını aparın və aşağıdakı şüşə paneldə rəqəmlərinizi oxuyun.',
  'help.ctx.atlas.bullet.1':
    'Xəritə: ziyarət edilmiş ölkələr onlara məxsus sabit rəngdə, planlaşdırılan ölkələr qırıq-qırıq konturla, arzular siyahısındakı ölkələr diaqonal ştrixlə, qalan hər yer isə boz göstərilir. Ölkənin səyahətlərini, məkanlarını, ilk və son ziyarətini görmək üçün kursoru onun üzərinə aparın.',
  'help.ctx.atlas.bullet.2':
    'Yuxarıdakı axtarış: ölkə və ya məkan adı yazın. Ölkə seçdikdə xəritə oraya uçur və onun pəncərəsini açır; məkan seçdikdə onun regionuna keçir ki, onu işarələyə biləsiniz.',
  'help.ctx.atlas.bullet.3':
    'Planlaşdırılan ölkələri göstər, sağ yuxarıda: qarşıdakı səyahətlərinizin ölkələrini göstərir. Açar yalnız belə səyahətləriniz olduqda görünür.',
  'help.ctx.atlas.bullet.4':
    'Aşağıdakı panel: ölkələr, səyahətlər, məkanlar, şəhərlər, günlər, qitələr və fasiləsiz seriyanızla Statistika bölməsi; hələ qarşıda olanlarla Arzular siyahısı bölməsi.',
  'help.ctx.atlas.bullet.5':
    'Regionlar: 5-ci miqyas səviyyəsindən etibarən xəritə ştatlara və əyalətlərə keçir, hər birini klikləməklə işarələmək və ya işarəni götürmək olar.',
  'help.ctx.atlas.bullet.6':
    'Dawarich: əlavə qoşulduqda statistikanın solundakı panel qeydlərinizə əsasən arzuları tamamlandı kimi işarələyir və ölkələr əlavə edir, lakin heç vaxt sizin təsdiqiniz olmadan.',
