  'help.guide.gallery-map.result':
    'İzin adını görmək üçün kursoru onun üzərinə gətirin. Qeydlər arasındakı qırıq xətti TREK çəkir; iz isə faktiki qeydə aldığınız marşrutdur.',
  'help.guide.gallery-map.tip.1': 'İzləri səyahət gündəliyi üçün Səyahət gündəliyi tənzimləmələrində söndürmək olar.',
  'help.guide.gallery-map.tip.2':
    'Məkan məlumatı olan qalereya fotoları həm Qalereya, həm də Xəritə paylaşıldıqda ictimai xəritədə də görünür.',
  // entry-fields
