  'help.guide.link-trip.tip.1':
    'Əlaqələndirilmiş səyahətin yanındakı × əlaqəni yenidən ləğv edir; yazdığınız qeydlər qalır.',
  'help.guide.link-trip.tip.2': 'Günü olan qeydlər, həmin günü neçə səyahət əhatə etsə də, yalnız bir dəfə sayılır.',
  // share-public
  'help.guide.share-public.title': 'Səyahət gündəliyini ictimai paylaşın',
