  'help.guide.contributors.tip.1': 'İştirakçılar bu TREK-dəki insanlar üçündür. Qalan hər kəs üçün ictimai link var.',
  // studio
  'help.guide.studio.title': 'Səyahət gündəliyini foto kitab kimi tərtib edin',
