  // archive-journey
  'help.guide.archive-journey.title': 'Səyahət gündəliyini arxivləşdirin və ya silin',
  'help.guide.archive-journey.goal': 'Bitmiş səyahət gündəliyini bağlayın və ya birdəfəlik silin.',
