  // ── Screen: journey-studio ─────────────────────────────────────────────────
  'help.ctx.journey-studio.title': 'Studio',
  'help.ctx.journey-studio.summary':
    'TREK Studio səyahət gündəliyini çap edilə bilən foto kitab kimi tərtib edir. O, gündəliyin üzərində açılır: solda səhifələr paneli və məzmun, ortada üzərində işlədiyiniz açılım, sağda onun xüsusiyyətləri. Avtomatik tərtibat qeydlərinizdən ilk qaralamanı qurur; bundan sonra hər şeyi daşımaq, kəsmək və yenidən üslublandırmaq sizin əlinizdədir, hər addım geri qaytarıla bilər.',
  'help.ctx.journey-studio.bullet.1':
    'Yuxarı panel: Səyahət gündəliyinə qayıt, Kitab görünüşü, geri qaytarma və təkrarlama, Səhifə formatı, Avtomatik tərtibat və İxrac et. Başlığın yanındakı Yadda saxlandı işarəsi kitabın nə vaxt saxlandığını göstərir.',
  'help.ctx.journey-studio.bullet.2':
    'Solda beş bölməli panel: Səhifələr, Məzmun (səyahət gündəliyinin fotoları və qeydləri), Elementlər (mətn, fiqurlar, xətlər, torlar, çərçivələr, ikonlar), Səyahət (səyahət gündəliyindən qurulan xəritələr, ölkələr, bayraqlar və nişanlar) və Tərtibatlar.',
  'help.ctx.journey-studio.bullet.3':
    'İş masası: daşma payı və təhlükəsiz kənar boşluqları ilə cari açılım, altında miqyas paneli, Görünüşə sığdır və sağda Bu açılımı endir.',
  'help.ctx.journey-studio.bullet.4':
    'Sağda Xüsusiyyətlər: seçilmiş elementin mövqeyi və ölçüsü, kəsimi və fokus nöqtəsi, doldurma və ya sığdırma, görünüşü, küncləri, çərçivəsi, qatların sırası və kilidi; heç nə seçilmədikdə isə səhifə nömrələri və sənəd.',
  'help.ctx.journey-studio.bullet.5':
    'Kitab cildlənmiş kitab formasındadır: üz qabığı, tək ilk səhifə, açılımlar, tək son səhifə və arxa qabıq. Səhifə nömrələri ilk səhifədən sayılır və göstərildiyi kimi çap olunur.',
  'help.ctx.journey-studio.bullet.6':
    'Bir neçə nəfər eyni anda dizayn edə bilər: hər kəs digərlərinin kursorlarını adları ilə görür, başqasının dəyişdirdiyi versiyanı yadda saxlama cəhdi isə onların işinin üzərinə yazmaq əvəzinə ziddiyyət kimi qayıdır.',
  // studio-auto-layout
  'help.guide.studio-auto-layout.title': 'Kitabı avtomatik qurun',
  'help.guide.studio-auto-layout.goal':
    'Bir kliklə gündəliyin qeydlərindən və fotolarından tam ilk qaralama əldə edin.',
  'help.guide.studio-auto-layout.step.1': 'Yuxarı paneldə Avtomatik tərtibat düyməsinə klikləyin.',
  'help.guide.studio-auto-layout.step.2':
    'Bütün kitab seçin: o, başlığınızı və səhifə ayarlarını saxlayaraq bütün səhifələri əvəz edir. Bu açılım yalnız ekrandakı açılımı yenidən qurur və qeyddən yaranmış açılımda təklif olunur.',
  'help.guide.studio-auto-layout.step.3':
    'Səhifələr panelinə nəzər salın. Əvvəlki variant daha çox xoşunuza gəlirdisə, Geri qaytar bütün tərtibatı geri alır.',
  'help.guide.studio-auto-layout.result':
    'Hər qeyd üçün ardıcıllıqla bir açılım, fotoları, başlığı və hekayəsi sizin üçün yerləşdirilmiş şəkildə. Hər element siz onu redaktə edənə qədər öz qeydini izləməyə davam edir.',
  'help.guide.studio-auto-layout.tip.1': 'Hər iki seçim adi geri qaytarma addımıdır, ona görə rahatlıqla sınayın.',
  'help.guide.studio-auto-layout.tip.2':
    'Avtomatik tərtibatın qeydə bağladığı element, siz ona Xüsusiyyətlər panelində toxunana qədər həmin qeydin redaktələrini izləyir; bu toxunuş əlaqəni qırır.',
