    'Paneldə Məzmun bölməsini açın. Fotolar səyahət gündəliyinin bütün şəkillərini, Qeydlər isə qeydləri mətnləri ilə birlikdə göstərir.',
  'help.guide.studio-content.step.2':
    'Fotonu açılıma və ya boş çərçivəyə sürükləyin, yaxud onun altındakı Bu səhifəyə əlavə et düyməsinə klikləyin. Fotolar yüklə hələ səyahət gündəliyində olmayan şəkilləri əlavə edir.',
