  'help.guide.place-participants.step.4':
    'Geri qaytarmaq üçün ada klikləyin. Hamı geri qayıtdıqda dayanacaq yenidən bütün qrupa aiddir.',
  'help.guide.place-participants.result':
    'Dayanacaqda seçdiyiniz səyahətçilər olur, qrupun qalanı isə həmin günortadan sonranı öz istədikləri kimi keçirir.',
  'help.guide.place-participants.tip.1':
    'İştirakçılar yalnız dayanacaq seçildikdə və yalnız birdən çox səyahətçisi olan səyahətdə görünür, ona görə məkanı məkanlar sütununda deyil, gün daxilində seçin.',
  'help.guide.place-participants.tip.2':
    'Heç kimin seçilməməsi hamının getdiyi deməkdir, buna görə dayanacaqda qalan son səyahətçini çıxarmaq olmur.',
  'help.guide.place-participants.tip.3': 'Öz hesabı olmayan qonaq da hər kəs kimi iştirakçı ola bilər.',
  // place-booking
  'help.guide.place-booking.title': 'Dayanacaqdakı rezervasiya',
  'help.guide.place-booking.goal': 'Dayanacağa aid rezervasiyanı oxuyun, onu açın və ona yenisini bağlayın.',
