  // place-navigation
  'help.guide.place-navigation.title': 'Məkanı xəritə tətbiqində və ya veb-saytında açın',
  'help.guide.place-navigation.goal': 'Məkanı sizi ora həqiqətən aparacaq tətbiqə ötürün.',
