  // place-track
  'help.guide.place-track.title': 'Treki oxuyun və ona öz rəngini verin',
  'help.guide.place-track.goal':
    'İdxal edilmiş gəzintinin uzunluğunu görün və onun xəttini xəritədəki digərlərindən ayırın.',
  'help.guide.place-track.step.1':
    'Məkanlar sütununda trekin sətrində onun xəttinin çəkildiyi rəngdə qısa bir cizgi var. Ona klikləyin.',
