  'help.guide.place-track.tip.2':
    'Hündürlüklərlə qeydə alınmış trek həmçinin ən yüksək və ən alçaq nöqtəsini, qalxma və enmə metrlərini və gəzintinin profilini göstərir.',
  'help.guide.place-track.tip.3':
    'İdxal gətirdiyi hər trekə öz rəngini verir, beləliklə iki gəzinti heç vaxt eyni rəngdə gəlmir.',

