  'help.ctx.trip-day-detail.title': 'Günün təfərrüatları',
  'help.ctx.trip-day-detail.summary':
    'Gün başlığının xəritənin üzərində açdığı panel: bütövlükdə gün, onun adı və tarixi, olacağınız yerdəki hava, həmin günə düşən rezervasiyalar və onun üçün rezerv edilmiş gecələr.',
  'help.ctx.trip-day-detail.bullet.1':
    'Günlər sütununda günün başlığına klikləyin, panel xəritənin ortasında açılır. Eyni başlığa yenidən və ya sağdakı X işarəsinə klikləmək onu bağlayır və günün seçimini ləğv edir.',
  'help.ctx.trip-day-detail.bullet.2':
    'Başlıqda günün adı və tarixi var. Adın yanındakı karandaş günün adını dəyişir, ikiqat ox isə paneli nazik zolağa yığır ki, xəritə yenidən açıq qalsın.',
  'help.ctx.trip-day-detail.bullet.3':
    'Yuxarıda günün havası göstərilir. Proqnoz sətri onun hansı yer üçün olduğunu bildirir: günün ilk dayanacağı və ya oyandığınız otel.',
  'help.ctx.trip-day-detail.bullet.4':
    'Rezervasiyalar həmin günün rezervasiyalarını göstərir, hər birinin növü, aid olduğu dayanacaq və vaxtları ilə. Yaşıl təsdiqlənib, kəhrəba rəngi isə hələ gözləyir deməkdir; bu yalnız göstəricidir, rezervasiyalar Rezervasiyalar bölməsində dəyişdirilir.',
  'help.ctx.trip-day-detail.bullet.5':
    'Yaşayış yeri bu günə düşən bütün rezerv edilmiş gecələri göstərir: müvafiq günlərdə Giriş və Çıxış, giriş vaxt aralığı, çıxış vaxtı və təsdiq nömrəsi ilə.',
  'help.ctx.trip-day-detail.bullet.6':
    'Yaşayış yeri əlavə et bu gün üçün gecə rezerv edir: səyahətin məkanlarından obyekti seçin, hansı günləri əhatə etdiyini göstərin, vaxtları və kodu əlavə edin.',
