  'help.guide.day-panel.step.5':
    'Yaşayış yeri bu günə düşən rezerv edilmiş gecələri müvafiq günlərdə Giriş və Çıxış ilə göstərir.',
  'help.guide.day-panel.step.6':
    'Başlıqdakı ikiqat ox paneli nazik zolağa yığır. Yanındakı X paneli bağlayır və günün seçimini ləğv edir.',
  'help.guide.day-panel.result':
    'Zolağa yığılmış panel xəritəni açıq saxlayır və günü seçili qoyur; bağlandıqda isə günün seçimi ləğv olunur və plan əvvəlki kimi qalır.',
